INSERT INTO public.preguntas
  ("año", numero, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema)
VALUES
  (2021, 1, '¿Qué ventaja tiene el empleo de aciloximetilésteres en lugar de ésteres simples en el diseño de profármacos de ácidos carboxílicos?:', 'Disminuye la velocidad de hidrólisis.', 'Aumenta la estabilidad del profármaco.', 'El grupo éster externo es más accesible al centro activo de las esterasas.', 'Facilita la bioactivación selectiva en el lugar de acción.', NULL, 'c', NULL, NULL),
  (2021, 2, '¿Qué inconveniente presenta el empleo de bases de Mannich como profármacos de amidas?:', 'Son inestables in vitro.', 'Aumentan excesivamente la lipofilia.', 'Son demasiado estables in vivo.', 'Forman con facilidad redes cristalinas muy estables.', NULL, 'a', NULL, NULL),
  (2021, 3, '¿Cuál de los siguientes sustituyentes presentes en la estructura de los antagonistas de los receptores de angiotensina II es ácido y aporta lipofilia?:', 'Bifenilo.', 'Hidroximetilo.', 'Tetrazol.', 'n-Butilo.', NULL, 'c', NULL, NULL),
  (2021, 4, '¿Qué papel desempeñan los fragmentos de betahidroxicarbonilo de las antraciclinas en su actividad biológica?:', 'Establecen enlaces covalentes con el ADN.', 'Establecen enlaces de hidrógeno con la topoisomerasa I.', 'Fijan la conformación activa a través de enlaces de hidrógeno intramoleculares.', 'Forman quelatos con el Fe3+ favoreciendo la formación de radicales hidroxilo.', NULL, 'd', NULL, NULL),
  (2021, 5, '¿Qué consecuencia tiene el cambio de posición de uno de los grupos hidroxilo del anillo de catecol en los derivados de ariletanolamina que actúan en los receptores adrenérgicos?:', 'Se favorece la degradación por la catecol-Ometil-transferasa.', 'Se pierde actividad al disminuir la analogía con el ligando endógeno.', 'Aumenta la estabilidad metabólica.', 'Se favorece la degradación por monoamino oxidasas.', NULL, 'c', NULL, NULL),
  (2021, 6, 'El catión metildiazonio es un metabolito activo de:', 'Procarbazina.', 'Ciclofosfamida.', 'Mecloretamina.', 'Busulfán.', NULL, 'a', NULL, NULL),
  (2021, 7, '¿Cuál de los siguientes fármacos se considera un inhibidor suicida?:', 'Lopinavir.', 'Captopril.', 'Selegilina.', 'Rivastigmina.', NULL, 'c', NULL, NULL),
  (2021, 8, '¿Cuál de las siguientes reacciones metabólicas de fase II NO conduce a un metabolito de mayor polaridad?:', 'Glucuronidación.', 'Acetilación.', 'Conjugación con sulfato.', 'Conjugación con glutatión.', NULL, 'b', NULL, NULL),
  (2021, 9, 'Un método general para obtener derivados del ácido barbitúrico consiste en la reacción entre:', 'Fenilhidrazina y un compuesto carbonílico enolizable.', 'Una 1,3-diamina y carbonato de etilo.', 'Acetilacetato de etilo, amoniaco y aldehídos aromáticos.', 'Un éster malónico convenientemente sustituido y urea.', NULL, 'd', NULL, NULL),
  (2021, 10, 'Las sulfonilureas ejercen su efecto hipoglucemiante al interaccionar con:', 'Canales de calcio dependientes de potencial.', 'Canales de sodio dependientes de potencial.', 'Bombas iónicas dependientes de ATP.', 'Canales de potasio dependientes de ATP.', NULL, 'd', NULL, NULL),
  (2021, 11, 'La síntesis de péptidos a partir de un aminoácido anclado sobre un soporte polimérico insoluble en el medio de reacción se denomina síntesis de:', 'Hantzsch.', 'Corey.', 'Merrifield.', 'Skraup.', NULL, 'c', NULL, NULL),
  (2021, 12, 'La toxicidad del paracetamol [N-(4-hidroxifenil)acetamida] a dosis elevadas, se debe a la formación de un metabolito altamente electrófilo. ¿De qué naturaleza química es este metabolito?:', 'Epóxido.', 'Catión aziridinio.', 'Iminoquinona.', 'Isocianato.', NULL, 'c', NULL, NULL),
  (2021, 13, 'En las relaciones cuantitativas entre la estructura química y la actividad biológica, el parámetro de Hammett se relaciona con:', 'La lipofilia de la molécula.', 'El efecto estérico de los sustituyentes.', 'La fracción de fármaco que alcanza la diana.', 'El efecto electrónico de los sustituyentes.', NULL, 'd', NULL, NULL),
  (2021, 14, 'El carbacol es un análogo de acetilcolina que tiene en su estructura un grupo carbamato en lugar del grupo éster. ¿Qué consecuencias tiene esta sustitución?:', 'El carbacol se hidroliza en medio ácido con mayor facilidad que la acetilcolina debido a la presencia del grupo carbamato.', 'El grupo carbamato confiere al carbacol estabilidad química y metabólica.', 'El grupo carbamato permite incrementar la afinidad por el receptor a través de una interacción π-π.', 'La sustitución bioisostérica del metilo por el grupo amino en el carbacol incrementa el efecto estérico, aumentando la afinidad por su diana terapéutica.', NULL, 'b', NULL, NULL),
  (2021, 15, '¿Cuál de las siguientes características estructurales es típica de los agentes alquilantes pertenecientes al grupo de las mostazas nitrogenadas?:', 'La presencia de grupos capaces de formar enlaces de hidrógeno.', 'La presencia de un grupo capaz de formar un catión aziridinio.', 'La presencia de una cadena peptídica corta y cargada positivamente.', 'La presencia de una estructura aromática plana y pobre en electrones.', NULL, 'b', NULL, NULL),
  (2021, 16, 'Para el diseño de los antídotos frente a los gases neurotóxicos sarín y tabún, se utilizó la siguiente estrategia:', 'Diseñar compuestos derivados de hidroxilamina capaces de hidrolizar la posición fosforilada en la acetilcolinesterasa y reactivar así la enzima rápidamente.', 'Diseñar compuestos derivados de hidroxilamina capaces de hidrolizar el residuo acetilado en la acetilcolinesterasa y reactivar así la enzima de forma controlada.', 'Diseñar compuestos derivados de hidroxicloroquina que debido a su elevada electrofilia son capaces de hidrolizar el residuo carbamoilado en la acetilcolinesterasa reactivando rápidamente la enzima.', 'Diseñar compuestos derivados de hidrazina capaces de hidrolizar la posición carbamoilada en la acetilcolinesterasa y reactivar la enzima rápidamente.', NULL, 'a', NULL, NULL),
  (2021, 17, 'La anfotericina B es un antifúngico que pertenece al siguiente grupo:', 'Polienos.', 'Triazoles.', 'Candinas.', 'Sulfamidas.', NULL, 'a', NULL, NULL),
  (2021, 18, 'Respecto a los hongos Mucorales:', 'Son sensibles a voriconazol.', 'Causan infecciones diagnosticables mediante la detección de β-1-3-D-glucano.', 'Causan infección sinusal, rino-órbitocerebral, broncopulmonar, cutánea o diseminada.', 'Tienen afinidad por tejidos queratinizados.', NULL, 'c', NULL, NULL),
  (2021, 19, '¿Qué mecanismo es responsable de la resistencia a las quinolonas?:', 'Presencia de mutaciones cromosómicas en los genes de la ADN girasa y de la topoisomerasa de tipo IV.', 'Modificación enzimática de la quinolona mediada por acetiltransferasas.', 'Adquisición de una β-lactamasa que hidroliza al fármaco.', 'Metilación del ARNr 23S, impidiendo la unión del antibiótico.', NULL, 'a', NULL, NULL),
  (2021, 20, '¿Cuál de los siguientes enunciados respecto a la toxina leucocidina Panton-Valentine de Staphylococcus aureus es INCORRECTO?:', 'Se identifica en la mayoría de cepas de S. aureus resistentes a meticilina asociadas a infecciones comunitarias.', 'Es causante de cuadros cutáneos graves.', 'Es una citotoxina.', 'Se relaciona con intoxicaciones alimentarias.', NULL, 'd', NULL, NULL),
  (2021, 21, '¿Cuál es la respuesta correcta respecto a Staphylococcus saprophyticus?:', 'Produce infecciones del aparato genitourinario en mujeres jóvenes.', 'Es sensible a fosfomicina.', 'Es sensible a novobiocina.', 'Es un estafilococo coagulasa-positivo.', NULL, 'a', NULL, NULL),
  (2021, 22, '¿Cuál de las siguientes bacterias es un bacilo gram-negativo que NO crece en agar MacConkey, es oxidasa positiva y está implicada en infecciones de heridas tras mordedura de animales?:', 'Pasteurella multocida.', 'Francisella tularensis.', 'Neisseria gonorrhoeae.', 'Enterobacter cloacae.', NULL, 'a', NULL, NULL),
  (2021, 23, '¿Cuál es la respuesta INCORRECTA respecto a las infecciones causadas por Legionella pneumophila?:', 'Son asintomáticas con relativa frecuencia.', 'La infección sintomática se presenta en una de las siguientes formas: fiebre de Pontiac o enfermedad de los legionarios.', 'El tratamiento de elección son los macrólidos o las fluoroquinolonas.', 'La fiebre de Pontiac se asocia con enfermedad pulmonar de base.', NULL, 'd', NULL, NULL),
  (2021, 24, '¿Cuál de las siguientes bacterias NO pertenece al denominado grupo HACEK?:', 'Achromobacter xylosoxidans.', 'Cardiobacterium hominis.', 'Kingella kingae.', 'Eikenella corrodens.', NULL, 'a', NULL, NULL),
  (2021, 25, '¿Cuál de las siguientes características fenotípicas supone una identificación presuntiva de Streptococcus pneumoniae?:', 'β-Hemólisis en agar sangre, sensibilidad a la optoquina, prueba de solubilidad en bilis positiva.', 'β-Hemólisis en agar sangre, resistencia a la optoquina, prueba de solubilidad en bilis negativa.', 'α-Hemólisis en agar sangre, sensibilidad a la optoquina, prueba de solubilidad en bilis positiva.', 'α-Hemólisis en agar sangre, resistencia a la optoquina, prueba de solubilidad en bilis positiva.', NULL, 'c', NULL, NULL),
  (2021, 26, 'Avibactam es un inhibidor de β-lactamasas con la EXCEPCIÓN de:', 'β-Lactamasa de espectro extendido (BLEE).', 'β-Lactamasa de clase C (ampC).', 'Carbapenemasa de tipo metalobetalactamasa.', 'Carbapenemasa de clase D (OXA-48).', NULL, 'c', NULL, NULL),
  (2021, 27, 'Señale la opción correcta respecto a microorganismo, enfermedad que causa y vector transmisor:', 'Coxiella burnetii, Fiebre Q, Ixodes spp.', 'Bartonella bacilliformis, Fiebre de Oroya, Hyalomma spp.', 'Borrelia burgdorferi, Enfermedad de Lyme, Aedes spp.', 'Rickettsia conorii, Fiebre botonosa mediterránea, Rhipicephalus spp.', NULL, 'd', NULL, NULL),
  (2021, 28, '¿Cuál de las siguientes afirmaciones respecto a la peste es correcta?:', 'El microorganismo causal de la peste bubónica es Yersinia enterocolitica serotipo O3.', 'Se transmite desde las ratas a los humanos mediante la picadura de pulgas del género Xenopsylla.', 'El periodo de incubación es de 30 a 60 días.', 'Sólo debe administrarse tratamiento en pacientes inmunodeprimidos, siendo vancomicina intravenosa el fármaco de elección.', NULL, 'b', NULL, NULL),
  (2021, 29, '¿Cuál de las siguientes opciones es INCORRECTA sobre la enfermedad zoonótica tularemia?:', 'El diagnóstico de laboratorio se basa principalmente en el cultivo y frotis de lesiones.', 'Los lagomorfos y los roedores son importantes reservorios animales.', 'Está causada por Francisella tularensis, cocobacilo gramnegativo.', 'Estreptomicina y gentamicina son fármacos de elección para todas las formas de tularemia grave, excepto meningitis.', NULL, 'a', NULL, NULL),
  (2021, 30, '¿Cuál de las siguientes afirmaciones con respecto a la “fiebre Q” es INCORRECTA?:', 'Se presenta como enfermedad febril autolimitada, neumonía, endocarditis o hepatitis.', 'El tratamiento de la endocarditis debe hacerse con doxiciclina durante 14 días.', 'Es una zoonosis que se adquiere por inhalación o, con menos frecuencia, por ingestión de leche no pasteurizada.', 'Para el diagnóstico de “fiebre Q” aguda se pueden utilizar técnicas de amplificación de ácidos nucleicos a partir de muestras clínicas (sangre, válvulas cardíacas o líquido articular).', NULL, 'b', NULL, NULL),
  (2021, 31, 'La colistina es un antibiótico de la familia de las polimixinas. ¿Cuál de las siguientes características es correcta?:', 'Las únicas formulaciones disponibles se administran por vía intravenosa y vía tópica.', 'Las polimixinas son activas frente a bacilos gramnegativos como P. aeruginosa, A. baumannii y las especies de Proteus.', 'Entre los efectos secundarios más frecuentes destacan la hepatotoxicidad y la neurotoxicidad irreversible, relacionada con la dosis.', 'La resistencia mediada por plásmidos se debe a la enzima MCR-1.', NULL, 'd', NULL, NULL),
  (2021, 32, '¿Cuál de los siguientes fármacos NO se utiliza para el tratamiento de la infección causada por Clostridioides difficile o presencia de sus recurrencias?:', 'Fidaxomicina.', 'Vancomicina vía oral.', 'Clindamicina.', 'Bezlotoxumab.', NULL, 'c', NULL, NULL),
  (2021, 33, '¿Cuál es el medio de cultivo microbiológico habitual para el diagnóstico de “tos ferina” a partir de muestras respiratorias?:', 'Bordet-Gengou.', 'Löwenstein-Jensen.', 'BCYE.', 'Thayer-Martin.', NULL, 'a', NULL, NULL),
  (2021, 34, '¿Cuál de las siguientes afirmaciones sobre Haemophilus influenzae es INCORRECTA?:', 'Es un cocobacilo gramnegativo.', 'Crece en agar MacConkey.', 'Existen seis serotipos capsulares.', 'El mecanismo de resistencia a las penicilinas más frecuente es la producción de βlactamasas.', NULL, 'b', NULL, NULL),
  (2021, 35, 'Una paciente de 48 años acude al Servicio de Urgencias de su hospital por presentar un cuadro de fiebre y dolor en hipocondrio derecho. Refiere consumo de verdura cruda en el Altiplano boliviano en su último viaje. ¿Qué patología es compatible con este cuadro clínico?:', 'Hidatidosis alveolar.', 'Distomatosis hepática.', 'Linfangitis aguda.', 'Clonorquiasis.', NULL, 'b', NULL, NULL),
  (2021, 36, '¿Cuál de los siguientes enunciados es INCORRECTO en relación al Síndrome de Katayama?:', 'Es un cuadro clínico causado por Schistosoma spp.', 'Sus manifestaciones clínicas más frecuentes son fiebre, erupción, hepatoesplenomegalia, broncoespasmo y eosinofilia.', 'La detección de huevos del parásito en heces es una herramienta diagnóstica muy sensible en la fase aguda.', 'Para su tratamiento se emplean prazicuantel y corticoides.', NULL, 'c', NULL, NULL),
  (2021, 37, '¿Cuál de los siguientes parásitos es de relevancia epidemiológica por su alta prevalencia entre la población infantil y causa una Enfermedad de Declaración Obligatoria?:', 'Entamoeba coli.', 'Trichinella spiralis.', 'Echinococcus granulosus.', 'Giardia lamblia.', NULL, 'd', NULL, NULL),
  (2021, 38, '¿Para qué sirve el planteamiento matemático de Heckel?:', 'Para analizar el comportamiento de materiales sólidos durante el proceso de compresión.', 'Para determinar la distribución bicompartimental para fármacos poco solubles.', 'Para determinar la viscosidad aparente en semisólidos con propiedades reopécticas.', 'Para calcular la velocidad de disolución en función del tamaño de partícula y del área superficial.', NULL, 'a', NULL, NULL),
  (2021, 39, '¿Qué relación existe entre el potencial Z y la floculación controlada de suspensiones?:', 'La floculación controlada consiste en la incorporación de sustancias quelantes como el EDTA que actúan como floculantes, lo que no guarda relación con el potencial Z.', 'La floculación controlada consiste en la adición de electrolitos para modificar el potencial Z y con ello el grado de floculación.', 'La floculación controlada consiste en la modificación del tamaño de partícula para modificar el grado de floculación, no el potencial Z.', 'La floculación controlada se realiza incorporando agentes viscosizantes que modifican las propiedades reológicas de las suspensiones y el potencial Z.', NULL, 'b', NULL, NULL),
  (2021, 40, '¿Es obligatorio realizar el ensayo de resistencia a la fractura en comprimidos según la Farmacopea Española?:', 'Sí. Está descrito como un ensayo obligatorio sobre lote final para comprobar su resistencia mecánica.', 'No. Está descrito como uno de los posibles ensayos para comprobar la resistencia mecánica de los comprimidos.', 'Sí, pero sólo en aquellos comprimidos destinados a su posterior recubrimiento y debe expresarse como valor mínimo.', 'No. Es un ensayo recomendable para comprobar la resistencia mecánica de los comprimidos, pero no es un ensayo oficial descrito en la Farmacopea.', NULL, 'b', NULL, NULL),
  (2021, 41, 'Indique cuál es el nombre del método industrial de fabricación de cápsulas gelatinosas blandas:', 'Método de Higuchi.', 'Método de Hausner.', 'Método de Scherer.', 'Método de Atkinson.', NULL, 'c', NULL, NULL),
  (2021, 42, '¿Para qué se utiliza el ensayo de endotoxinas bacterianas?:', 'Para determinar la toxicidad de preparados farmacéuticos debido a bacterias anaerobias.', 'Para detectar la posible contaminación de formulaciones farmacéuticas con pirógenos.', 'Para detectar una posible contaminación de un preparado farmacéutico con bacterias Gram+.', 'Para estimar el grado de toxicidad que pueda tener la contaminación de un preparado farmacéutico con una cierta especie bacteriana.', NULL, 'b', NULL, NULL),
  (2021, 43, 'El diámetro equivalente de Stokes de una partícula se define como:', 'El diámetro de una esfera de igual densidad que la partícula que sedimenta a la misma velocidad que la partícula.', 'El diámetro de una esfera que tiene la misma superficie que la partícula.', 'El diámetro de una esfera que tiene el mismo volumen que la partícula.', 'El diámetro de una esfera que produce la misma variación en la resistencia eléctrica de la corriente que circula entre dos electrodos cuando se realiza la medida en el contador Coulter.', NULL, 'a', NULL, NULL),
  (2021, 44, 'En el proceso de desecación, si la presión de vapor de agua en el sólido es mayor que en el aire:', 'Se producirá transferencia neta de vapor de agua del sólido al aire hasta que se igualen las presiones.', 'Se producirá transferencia de vapor de agua del aire al sólido que adquirirá un mayor contenido de humedad.', 'No se producirá transferencia de vapor de agua del aire al sólido y ambas se mantendrán en equilibrio dinámico.', 'Se producirá transferencia de vapor de agua del sólido al aire cuando la humedad relativa del gas sea del 100%.', NULL, 'a', NULL, NULL),
  (2021, 45, 'La visión en profundidad permite determinar las posiciones relativas de los objetos. El fenómeno que consiste en la percepción de esta profundidad, obtenida a partir de las disparidades retinianas que aparecen como consecuencia de la separación horizontal de los globos oculares, se denomina:', 'Estereopsis.', 'Amaurosis.', 'Estrabismo.', 'Ambliopía.', NULL, 'a', NULL, NULL),
  (2021, 46, '¿Cómo se denomina el efecto de la unión del oxígeno con la hemoglobina que produce el desplazamiento del dióxido de carbono hacia la sangre?:', 'Efecto Haldane.', 'Efecto Bohr.', 'Efecto Doppler.', 'Efecto Venturi.', NULL, 'a', NULL, NULL),
  (2021, 47, '¿Cuáles son los órganos sensitivos del laberinto membranoso que se encuentran en el aparato vestibular y detectan la orientación de la cabeza con respecto a la gravedad?:', 'Máculas del utrículo y del sáculo.', 'Conductos cocleares.', 'Conductos endolinfáticos.', 'Órganos tendinosos de Golgi.', NULL, 'a', NULL, NULL),
  (2021, 48, '¿En qué lugar se produce la secreción de la colecistoquinina (CCK)?:', 'Células G del estómago.', 'Células S del duodeno.', 'Células I del duodeno y del yeyuno.', 'Células K del intestino grueso.', NULL, 'c', NULL, NULL),
  (2021, 49, '¿Cuál de las siguientes fases del electrocardiograma corresponde a la repolarización de los ventrículos?:', 'Complejo QRS.', 'Onda T.', 'Intervalo PR.', 'Intervalo QT.', NULL, 'b', NULL, NULL),
  (2021, 50, '¿Cuál de los siguientes fenómenos NO está asociado a un desplazamiento hacia la derecha de la curva de disociación de oxígeno-hemoglobina?:', 'Aumento del 2,3-DPG.', 'Disminución de la temperatura.', 'Aumento de la pCO2.', 'Disminución del pH.', NULL, 'b', NULL, NULL),
  (2021, 51, 'Señale la respuesta INCORRECTA respecto a la gastrina:', 'Estimula la secreción de ácido gástrico por las células parietales.', 'Estimula la secreción de pepsinógeno por las células principales.', 'Es secretada por las células M del antro y las células K del duodeno y yeyuno.', 'Mantiene la estructura de la mucosa gástrica.', NULL, 'c', NULL, NULL),
  (2021, 52, 'El cociente entre el trabajo y el gasto de energía química total (consumo de oxígeno) se denomina eficiencia de la contracción cardíaca y sus valores normales están entre:', '5-10%.', '20-25%.', '45-50%.', '>60%.', NULL, 'b', NULL, NULL),
  (2021, 53, 'De las siguientes células de sostén, señale cuál NO pertenece al sistema nervioso central:', 'Células de Schwann.', 'Astrocitos.', 'Microglía.', 'Oligodendrocitos.', NULL, 'a', NULL, NULL),
  (2021, 54, 'Existe un neurotransmisor que al estimularse el receptor postsináptico se sintetiza casi al instante mediante activación enzimática y, a continuación, difunde fuera de los terminales presinápticos durante unos segundos en lugar de ser liberado en paquetes vesiculares. Señale cuál es:', 'Ácido γ-aminobutírico (GABA).', 'Acetilcolina.', 'Óxido nítrico.', 'Dopamina.', NULL, 'c', NULL, NULL),
  (2021, 55, 'El túbulo colector cortical cumple tres funciones fundamentales para la regulación del medio interno: absorción de Na+, secreción de K+ y secreción de H+/formación de HCO3-. Ésta última función se lleva a cabo en un tipo de células que se denominan:', 'Células principales.', 'Células yuxtaglomerulares.', 'Células corticales.', 'Células intercaladas.', NULL, 'd', NULL, NULL),
  (2021, 56, 'Fisiológicamente, la hormona paratiroidea (PTH):', 'Inhibe la reabsorción de calcio en los riñones.', 'Estimula la reabsorción de fosfato en los riñones.', 'Estimula la resorción de calcio y fosfato en el hueso.', 'Inhibe la resorción de calcio y fósforo en el hueso.', NULL, 'c', NULL, NULL),
  (2021, 57, 'En la pared de los primeros centímetros del duodeno, especialmente entre el píloro gástrico y la ampolla de Vater, existe un amplio conjunto de glándulas mucosas que secretan moco. Estas glándulas reciben el nombre de:', 'Lieberkühn.', 'Paneth.', 'Brunner.', 'Oxíntica.', NULL, 'c', NULL, NULL),
  (2021, 58, 'En el control hipotalámico de la alimentación existen dos tipos de neuronas: 1) las neuronas proopiomelanocortina (POMC) que producen la hormona estimulante α de los melanocitos αMSH) y el transcrito regulado por la cocaína y la anfetamina (CART) y 2) las neuronas que producen la proteína relacionada con el gen Agouti (AGRP) y el neuropéptido Y (NPY). Señale qué hormona activa las neuronas AGRP-NPY estimulando la ingesta:', 'Leptina.', 'Insulina.', 'Grelina.', 'Colecistoquinina.', NULL, 'c', NULL, NULL),
  (2021, 59, 'Los factores fisiológicos más importantes que regulan la secreción de la hormona antidiurética (ADH) desde la neurohipófisis son la regulación osmótica y hemodinámica. Adicionalmente, existen otros factores que afectan a la secreción de esta hormona. Señale el factor desencadenante de su secreción:', 'Consumo de alcohol.', 'Náuseas.', 'Descenso de la osmolaridad plasmática.', 'Aumento del volumen plasmático.', NULL, 'b', NULL, NULL),
  (2021, 60, 'Con respecto a la serie granulocítica, indique cuál de estas células es la más madura:', 'Mielocito.', 'Metamielocito.', 'Mieloblasto.', 'Promielocito.', NULL, 'b', NULL, NULL),
  (2021, 61, '¿Cuál de las siguientes alteraciones morfológicas se buscará en primer lugar en el frotis de un paciente que acude a urgencias con deterioro neurológico y plaquetas por debajo de 100.000/L?:', 'Esferocitos.', 'Esquistocitos.', 'Acantocitos.', 'Equinocitos.', NULL, 'b', NULL, NULL),
  (2021, 62, 'El test de Coombs directo es una prueba diagnóstica clave en:', 'Anemia hemolítica del recién nacido utilizando sangre materna.', 'Anemia hemolítica adquirida de origen inmune.', 'Anemia hemolítica de causa no inmune.', 'Anemia no hemolítica.', NULL, 'b', NULL, NULL),
  (2021, 63, 'Indique el grupo sanguíneo del sistema ABO considerado como receptor universal:', 'Grupo AB.', 'Grupo A.', 'Grupo 0.', 'Grupo B.', NULL, 'a', NULL, NULL),
  (2021, 64, '¿Qué hallazgo esperaría encontrar típicamente en una leucemia mieloide aguda tipo M3 clásica?:', 'Leucopenia.', 'Neutrofilia.', 'Trombocitosis.', 'Poliglobulia.', NULL, 'a', NULL, NULL),
  (2021, 65, 'Indique cuál de los siguientes NO es un hallazgo de laboratorio en el mieloma múltiple:', 'Hipocalcemia.', 'Proteinuria de Bence-Jones.', 'Anemia.', 'Hiperproteinemia.', NULL, 'a', NULL, NULL),
  (2021, 66, 'Indique cuál de los siguientes parámetros descarta la existencia de trombosis si su valor está dentro de la normalidad:', 'Proteína C.', 'D-dímero.', 'Antitrombina III.', 'Proteína S.', NULL, 'b', NULL, NULL),
