  (2021, 69, 'En las patologías neurológicas asociadas a depósitos de cuerpos de Lewy, éstos están formados por:', 'Proteína tau.', 'α-Sinucleína.', 'β-Sinucleína.', 'Amiloide β.', NULL, 'b', NULL, NULL),
