  (2021, 85, 'Referente a los fármacos para la artritis reumatoide, ¿qué relación fármaco -diana molecular es INCORRECTA?:', 'Rituximab - anticuerpo monoclonal frente a CD20 de linfocitos B.', 'Abatacept - proteína de fusión frente al TNF-α.', 'Tocilizumab - anticuerpo monoclonal frente al receptor IL-6.', 'Tofacitinib - inhibidor selectivo de Janus Kinasa (JAK).', NULL, 'b', NULL, NULL),
  (2021, 86, '¿Cuál de los siguientes antipsicóticos tiene indicación en el manejo de la agitación y/o agresividad en la enfermedad de Alzheimer?:', 'Sulpirida.', 'Risperidona.', 'Clozapina.', 'Zuclopentixol.', NULL, 'b', NULL, NULL),
  (2021, 87, '¿Cuál de las siguientes afirmaciones sobre omeprazol es INCORRECTA?:', 'Se recomienda tomar en ayunas.', 'Puede causar hipermagnesemia en tratamientos de larga duración.', 'Puede disminuir la absorción de vitamina B12.', 'La máxima inhibición ácida se consigue a los 3-4 días de tratamiento.', NULL, 'b', NULL, NULL),
  (2021, 88, 'En pacientes en tratamiento para el control de la dislipemia es INCORRECTO que:', 'Los fibratos potencian el efecto de los anticoagulantes orales.', 'La combinación de fibratos y estatinas incrementa el riesgo de rabdomiólisis.', 'Las estatinas son el fármaco de elección en el tratamiento de las dislipemias en embarazadas.', 'La combinación de fluconazol y atorvastatina puede incrementar las concentraciones de atorvastatina.', NULL, 'c', NULL, NULL),
