  (2021, 97, '¿Cuál de los siguientes antiepilépticos sería de elección en un paciente que sufre de trastorno bipolar?:', 'Fenitoína.', 'Topiramato.', 'Lamotrigina.', 'Pregabalina.', NULL, 'c', NULL, NULL),
  (2021, 98, '¿Cuál de las siguientes opciones respecto a los nitratos es INCORRECTA?:', 'Sus efectos son dependientes de la presencia intacta y funcional del endotelio vascular.', 'Disminuyen la precarga.', 'Están indicados en cuadros de angina de pecho.', 'Se unen a receptores con actividad guanililciclasa.', NULL, 'a', NULL, NULL),
  (2021, 99, 'En relación con la unión de fármacos a proteínas plasmáticas, señale la opción correcta:', 'Los fármacos con un alto grado de unión a proteínas plasmáticas suelen tener volúmenes aparentes de distribución elevados.', 'La interacción entre los fármacos y la albúmina sérica es inespecífica.', 'La unión de los fármacos a las proteínas plasmáticas es un proceso saturable.', 'La unión de los fármacos a las proteínas plasmáticas no modifica la velocidad de distribución del fármaco.', NULL, 'c', NULL, NULL),
  (2021, 101, '¿Qué subtipo de proteínas G regula la actividad de la fosfolipasa C?:', 'Proteínas Gs.', 'Proteínas Gi.', 'Proteínas Go.', 'Proteínas Gq.', NULL, 'd', NULL, NULL),
