  (2021, 153, 'El pH de una disolución 0,01 M de dihidrógeno fosfato de sodio [pKa1 (H3PO4) = 2,15; pKa2 (H3PO4) = 7,21; pKa3 (H3PO4) = 12,33]:', 'Es menor de 3,0.', 'Está entre 3,0 y 7,0.', 'Está entre 7,0 y 9,0.', 'Es mayor de 9,0.', NULL, 'b', NULL, NULL),
  (2021, 154, 'La sensibilidad de un método analítico se evalúa a partir de:', 'El coeficiente de variación de una serie de medidas.', 'El error relativo de la medida.', 'La pendiente de la recta de calibrado.', 'La ordenada en el origen de la recta de calibrado.', NULL, 'c', NULL, NULL),
  (2021, 155, 'En la determinación del Fe(II) con dicromato de potasio como reactivo titulador, para la detección del punto final de la valoración se utiliza:', 'El indicador murexida, ya que posee propiedades redox.', 'Una pila electroquímica formada por un electrodo indicador de Fe y un electrodo de referencia.', 'Una pila electroquímica formada por un electrodo indicador de Pt y un electrodo de referencia.', 'El engrudo de almidón porque se une al reactivo titulador indicando el punto final.', NULL, 'c', NULL, NULL),
  (2021, 156, 'La utilización de disolventes halogenados, como el diclorometano, para disolver un compuesto fluorescente produce:', 'Un aumento de la señal de fluorescencia, porque aumenta la probabilidad de producirse un cruce entre sistemas.', 'Una disminución de la señal de fluorescencia, porque aumenta la probabilidad de producirse un cruce entre sistemas.', 'Un aumento de la señal de fluorescencia, porque aumenta la probabilidad de conversión externa.', 'Una disminución de la señal de fluorescencia, porque aumenta la probabilidad de relajación vibracional.', NULL, 'b', NULL, NULL),
  (2021, 157, 'Atendiendo a la ecuación de Van Deemter, la altura equivalente del plato teórico aumenta cuando:', 'Aumenta el diámetro de partícula de la fase estacionaria.', 'Disminuye el diámetro interno de la columna.', 'Disminuye el espesor del recubrimiento líquido en la fase estacionaria.', 'Aumenta el coeficiente de difusión del soluto en la fase estacionaria.', NULL, 'a', NULL, NULL),
  (2021, 158, '¿Cuál de los sistemas de ionización en espectrometría de masas utiliza iones gaseosos reactivos para lograr la obtención de iones?:', 'Bombardeo por impacto de electrones.', 'Bombardeo por átomos rápidos.', 'MALDI (desorción/ionización por láser asistida con matriz).', 'Ionización química.', NULL, 'd', NULL, NULL),
