  (2021, 160, 'La fuente de acoplamiento inductivo en espectrometría de emisión atómica (ICP-AES), denominada antorcha, está formada por:', 'Un tubo por el que fluye una corriente de argón.', 'Tres tubos concéntricos por los que fluyen corrientes de argón.', 'Un tubo por el que fluye una corriente de aire-hidrógeno.', 'Tres tubos concéntricos por los que fluyen corrientes de aire-hidrógeno.', NULL, 'b', NULL, NULL),
  (2021, 161, 'Un aumento de la temperatura produce un ensanchamiento de las líneas espectrales en espectrometría atómica:', 'Por efecto Doppler y por presión.', 'Por ensanchamiento natural y por efecto Doppler.', 'Por efecto Planck y por presión.', 'Por ensanchamiento natural y por efecto Planck.', NULL, 'a', NULL, NULL),
  (2021, 162, 'Una valoración fotométrica se realizó a una longitud de onda en la que ni el analito ni el producto de la reacción son absorbentes y solo absorbe el titulador. En estas condiciones la absorbancia:', 'Crece constantemente desde el inicio hasta el final de la valoración.', 'Solo crece después del punto de equivalencia.', 'Solo crece antes del punto de equivalencia.', 'No varía después del punto de equivalencia.', NULL, 'b', NULL, NULL),
  (2021, 163, 'En un espectrómetro de infrarrojo (IR), el cloro molecular (Cl2):', 'Genera una banda de absorción en la región de 1500 cm-1 que corresponde a la vibración de tensión.', 'Genera una banda de absorción en la región de 2500 cm-1 que corresponde a la vibración de flexión.', 'Genera una banda de absorción en la región de 4000 cm-1.', 'No se observa absorción en la región IR porque esta molécula carece de momento dipolar permanente.', NULL, 'd', NULL, NULL),
  (2021, 164, 'En cromatografía de gases, una elución con rampa o gradiente de temperatura es la opción más adecuada para la resolución de analitos:', 'Volátiles con puntos de ebullición muy diferentes.', 'Volátiles con puntos de ebullición muy semejantes.', 'Volátiles y no volátiles con puntos de ebullición muy diferentes.', 'Volátiles y no volátiles con puntos de ebullición muy semejantes.', NULL, 'a', NULL, NULL),
