  (2021, 184, 'En una distribución platicúrtica de valores de una variable cuantitativa, los valores:', 'Se distribuyen según la Ley Normal.', 'Se acumulan en las colas en comparación con una distribución normal.', 'Se acumulan en el centro de la distribución en comparación con una distribución normal.', 'Se distribuyen siempre asimétricamente.', NULL, 'b', NULL, NULL),
  (2021, 185, 'Señale cuál de las siguientes afirmaciones acerca de la dispersión en una serie de datos es cierta:', 'La varianza es la raíz cuadrada de la desviación estándar.', 'La desviación estándar es la media de las diferencias entre cada valor de la variable y la media aritmética de la distribución de los valores.', 'La varianza es la media de las diferencias entre cada valor de la variable y la media aritmética de la distribución de los valores.', 'La varianza es la media de la suma de cuadrados de las diferencias entre cada valor de la variable y la media aritmética de la distribución de los valores.', NULL, 'd', NULL, NULL),
  (2021, 186, 'Indique cuál de las siguientes afirmaciones acerca de los percentiles es verdadera:', 'No son medidas de posición.', 'Los cuartiles son cada uno de los 4 valores de una variable que dividen la muestra ordenada en 4 grupos de igual tamaño.', 'Los cuartiles son cada uno de los 3 valores de una variable que dividen la muestra ordenada en 4 grupos de igual tamaño.', 'Los cuartiles son cada uno de los 4 valores de una variable que dividen la muestra ordenada en 3 grupos de igual tamaño.', NULL, 'c', NULL, NULL),
  (2021, 187, '¿Cuál de los siguientes NO es un ejemplo de acuerdo de riesgo compartido?:', 'El precio al que la farmacia de un hospital adquiere el romiplostin disminuye un 20% si se supera la compra de 1.000 unidades anuales.', 'La farmacia de un hospital negocia un descuento del 40% en el precio del posaconazol de un determinado laboratorio.', 'Un laboratorio financia el tratamiento a partir del décimo ciclo de quimioterapia con su nuevo anticuerpo monoclonal para cáncer de mama.', 'El precio que se paga a un laboratorio por la compra de somatropina varía en función de la altura que crezca el paciente en un determinado tiempo.', NULL, 'b', NULL, NULL),
