-- INSERT preguntas FIR 2021 (convocatoria FSE 2021, Farmacia)
-- Fuente: Cuaderno_2021_F_0_C.pdf + Respuestas_2021.xlsx
-- Generado: 207 preguntas validas de 210 impresas (3 anuladas excluidas: 100, 182, 194)
-- tema queda NULL: se clasificara en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2021) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2021 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

